import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0032: Herd workspaces and local Git status","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0032-herd-workspaces-and-read-only-git-status.md","filePath":"adrs/0032-herd-workspaces-and-read-only-git-status.md","lastUpdated":1789092097000}`),u={name:`adrs/0032-herd-workspaces-and-read-only-git-status.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[26]||=a(`<h1 id="adr-0032-herd-workspaces-and-local-git-status" tabindex="-1">ADR-0032: Herd workspaces and local Git status <a class="header-anchor" href="#adr-0032-herd-workspaces-and-local-git-status" aria-label="Permalink to “ADR-0032: Herd workspaces and local Git status”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-09-03 · Refines <a href="/adrs/0019-pens-as-folders">ADR-0019</a> and <a href="/adrs/0026-main-actor-publication-and-worker-io">ADR-0026</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2>`,3),c(`p`,null,[l[2]||=i(`ADR-0019 made a `,-1),r(m,{term:`pen`},{default:n(()=>[...l[0]||=[i(`Pen`,-1)]]),_:1}),l[3]||=i(` an inspectable GOAT-owned folder with instructions, memory, and references. That remains useful application state, but it is not necessarily the folder in which a person does their work. A software Pen needs a user-owned project folder, while research and personal Pens may need no folder at all. Copying a repository into GOAT Home, putting memory inside a repository, or treating every attached folder as prompt `,-1),r(m,{term:`context-window`},{default:n(()=>[...l[1]||=[i(`context`,-1)]]),_:1}),l[4]||=i(` would violate ownership and exhaust small local model context windows.`,-1)]),l[27]||=a(`<p>Git can give a useful, immediate signal for a bound project folder. SwiftUI supplies native presentation primitives, but no public Git repository status API. Manually interpreting <code>.git</code> would mishandle valid layouts such as linked worktrees.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="pens-optionally-bind-one-user-owned-workspace" tabindex="-1">Pens optionally bind one user-owned workspace <a class="header-anchor" href="#pens-optionally-bind-one-user-owned-workspace" aria-label="Permalink to “Pens optionally bind one user-owned workspace”">​</a></h3><p>A Pen persists an optional absolute <code>PenWorkspace</code> path and bookmark in <code>project.json</code>. GOAT&#39;s existing Pen folder remains the control sidecar for instructions and memory. A workspace is never silently moved, merged, populated with GOAT metadata, or deleted when its Pen is deleted.</p>`,4),c(`p`,null,[l[8]||=i(`The global `,-1),c(`strong`,null,[l[6]||=i(`Default `,-1),r(m,{term:`herd`},{default:n(()=>[...l[5]||=[i(`Herd`,-1)]]),_:1}),l[7]||=i(` location`,-1)]),l[9]||=i(` is a convenience for creating future folders, not a policy. It defaults to `,-1),l[10]||=c(`code`,null,`~/Projects`,-1),l[11]||=i(`, is user-selectable in Settings, and changes no existing binding. New Pens offer three explicit choices: create a folder in the Herd, bind an existing folder, or create no workspace yet. Creation slugifies the Pen name and uses `,-1),l[12]||=c(`code`,null,`-1`,-1),l[13]||=i(`, `,-1),l[14]||=c(`code`,null,`-2`,-1),l[15]||=i(`, and later suffixes rather than adopting a conflicting folder.`,-1)]),c(`p`,null,[l[17]||=i(`Folders and references are not prompt context. The existing Pen brief remains explicit system content, while memory remains under its deterministic budget. Future user-selected chat worksets and permissioned workspace `,-1),r(m,{term:`tool`},{default:n(()=>[...l[16]||=[i(`tools`,-1)]]),_:1}),l[18]||=i(` must declare their own bounded context cost rather than reading a workspace recursively.`,-1)]),l[28]||=a(`<h3 id="git-is-local-status-is-read-only-and-initialization-is-opt-in" tabindex="-1">Git is local, status is read-only, and initialization is opt-in <a class="header-anchor" href="#git-is-local-status-is-read-only-and-initialization-is-opt-in" aria-label="Permalink to “Git is local, status is read-only, and initialization is opt-in”">​</a></h3><p>The Pen header shows the current branch and a compact clean, changed, or conflict state. Its workspace section and status popover reveal staged, modified, untracked, conflict, and local ahead/behind counts. The sidebar can later use the same compact status without giving each chat a misleading branch badge. A chat does not own the branch because every chat in a Pen shares the bound working folder.</p><p>GOAT invokes the system <code>/usr/bin/git</code> through Foundation <code>Process</code> on a worker actor. It calls <code>rev-parse --show-toplevel</code>, <code>status --porcelain=v2 --branch</code>, <code>--version</code>, and read-only configuration queries for status. A visible <strong>Initialize Git repository</strong> option appears only when Git is available while creating a new folder, and only that explicit selection can call <code>git init --quiet</code> in the newly created folder. It adds no contents, creates no remote, and does not require a configured identity. It sets <code>GIT_TERMINAL_PROMPT=0</code>, clears environment variables that could redirect the working tree, uses no network command, and never fetches, stages, commits, switches, or merges. Git&#39;s porcelain output is the parser contract, preserving Git&#39;s own semantics for worktrees and detached HEADs.</p><p>Settings reports whether Git is available and whether the optional global name and email identity are configured. Missing Git is an integration warning, not an application failure. A non-Git workspace quietly reports that it is not a repository. Identity is advisory until GOAT offers a user-authorized write action.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2>`,5),c(`ul`,null,[l[22]||=c(`li`,null,`Pens can be useful local workspaces without coupling GOAT's memory files to repositories.`,-1),l[23]||=c(`li`,null,`Existing Pens load as unbound, so this adds no migration or destructive file operation.`,-1),l[24]||=c(`li`,null,`Workspace binding, Git probing, and folder creation stay off the main actor. UI state receives only Sendable result values.`,-1),c(`li`,null,[l[20]||=i(`Folder paths and Git status consume no model `,-1),r(m,{term:`token`},{default:n(()=>[...l[19]||=[i(`tokens`,-1)]]),_:1}),l[21]||=i(`. No repository contents enter a prompt by default.`,-1)]),l[25]||=c(`li`,null,[i(`The user-facing Herd root and `),c(`code`,null,`PenWorkspace`),i(` form a reusable core for a future GOAT CLI or API, without duplicating folder and Git behaviour outside the app.`)],-1)]),l[29]||=c(`h2`,{id:`alternatives-considered`,tabindex:`-1`},[i(`Alternatives considered `),c(`a`,{class:`header-anchor`,href:`#alternatives-considered`,"aria-label":`Permalink to “Alternatives considered”`},`​`)],-1),l[30]||=c(`p`,null,[i(`Make the GOAT Pen sidecar the project root (rejected: it places managed memory and metadata in a user repository), copy external folders into GOAT Home (rejected: duplicates data and obscures ownership), inject a folder tree into every request (rejected: high and unpredictable token cost), parse `),c(`code`,null,`.git`),i(` directly (rejected: incomplete worktree semantics), and use Git status as a chat-row badge (rejected: one mutable workspace state is shared by the Pen, not owned by an individual chat).`)],-1)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};